import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('React.memo', () => {
  test('Renders the greeting', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#greeting');
if (!el) throw new Error('No element with id "greeting" found');
if (!el.textContent.includes('Hello, React!'))
  throw new Error('Greeting should say "Hello, React!"');
  });

  test('Initial count is 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el || !el.textContent.includes('0'))
  throw new Error('Initial count should be 0');
  });

  test('Bump button increments count', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#bump');
if (!btn) throw new Error('No button with id "bump" found');
btn.click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('1'))
  throw new Error('Count should be 1 after clicking Bump');
  });

  test('Greeting still renders after parent re-renders', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#greeting');
if (!el || !el.textContent.includes('Hello, React!'))
  throw new Error('Greeting should still say "Hello, React!" after a re-render');
  });
});
